function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // head
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 50 + 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 50 - 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  // hands
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 20 * Math.sin(t), H/2 + 70, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 50 - 20 * Math.sin(t), H/2 + 70, 10, 0, 2 * Math.PI);
  ctx.fill();

  // explosion of tension
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2, H/2 + 100, 10 + 5 * i, 0, 2 * Math.PI);
    ctx.lineWidth = 2 - 0.1 * i;
    ctx.strokeStyle = 'black';
    ctx.stroke();
    ctx.rotate(Math.sin(t + i));
  }

  ctx.restore();
}
